import{_ as n,C as i,o as t,c as s,a2 as a,b as d,w as o,a as c,E as l,a3 as u}from"./chunks/framework.BB06nUeW.js";const q=JSON.parse('{"title":"Feature Inventory & Architectural Traces","description":"","frontmatter":{},"headers":[],"relativePath":"01-features.md","filePath":"01-features.md"}'),h={name:"01-features.md"};function m(b,e,p,f,g,y){const r=i("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="feature-inventory-architectural-traces" tabindex="-1">Feature Inventory &amp; Architectural Traces <a class="header-anchor" href="#feature-inventory-architectural-traces" aria-label="Permalink to &quot;Feature Inventory &amp; Architectural Traces&quot;">​</a></h1><h2 id="core-banking-features" tabindex="-1">Core Banking Features <a class="header-anchor" href="#core-banking-features" aria-label="Permalink to &quot;Core Banking Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Feature Name</th><th>Core Implementation Files</th><th>Description</th></tr></thead><tbody><tr><td><strong>F1</strong></td><td>Immutable Double-Entry Ledger Transfers</td><td><code>transaction.controller.js</code>, <code>ledger.model.js</code></td><td>ACID-compliant fund movements with paired debit/credit records.</td></tr><tr><td><strong>F2</strong></td><td>Token Blacklist &amp; Secure Logout</td><td><code>auth.controller.js</code>, <code>blackList.model.js</code></td><td>Server-side token invalidation preventing post-logout replay.</td></tr><tr><td><strong>F3</strong></td><td>Payee Beneficiary Management</td><td><code>beneficiary.controller.js</code>, <code>beneficiary.model.js</code></td><td>Saved recipient directory with account validation and anti-IDOR checks.</td></tr><tr><td><strong>F4</strong></td><td>Financial Statement CSV Exporter</td><td><code>transaction.controller.js:exportTransactionsCSV</code></td><td>On-the-fly streaming RFC-4180 compliant CSV account statements.</td></tr><tr><td><strong>F5</strong></td><td>Real-Time React Banking Dashboard</td><td><code>frontend/src/pages/Dashboard.jsx</code>, <code>api.js</code></td><td>Single-page client with live balance calculation and transaction feed.</td></tr></tbody></table><hr><h2 id="f1-immutable-double-entry-ledger-transfers" tabindex="-1">F1: Immutable Double-Entry Ledger Transfers <a class="header-anchor" href="#f1-immutable-double-entry-ledger-transfers" aria-label="Permalink to &quot;F1: Immutable Double-Entry Ledger Transfers&quot;">​</a></h2><p>Executes fund transfers between accounts within an atomic MongoDB session, creating non-modifiable debit and credit records.</p>',6)),(t(),d(u,null,{default:o(()=>[l(r,{id:"mermaid-103",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Req%5BPOST%20%2Fapi%2Ftransactions%2Ftransfer%5D%20--%3E%20Val%7BValidate%20Inputs%7D%0A%20%20%20%20Val%20--%3E%7CSelf-Transfer%20%2F%20Non-numeric%20%2F%20Negative%7C%20Err1%5B400%20Bad%20Request%5D%0A%20%20%20%20Val%20--%3E%7CValid%7C%20AuthCheck%7BSender%20Owns%20Account%3F%7D%0A%20%20%20%20AuthCheck%20--%3E%7CNo%7C%20Err2%5B403%20Forbidden%20Anti-IDOR%5D%0A%20%20%20%20AuthCheck%20--%3E%7CYes%7C%20Session%5BStart%20MongoDB%20ACID%20Transaction%5D%0A%20%20%20%20Session%20--%3E%20BalCheck%7BAvailable%20Balance%20%3E%3D%20Amount%3F%7D%0A%20%20%20%20BalCheck%20--%3E%7CNo%7C%20Err3%5B400%20Insufficient%20Funds%5D%0A%20%20%20%20BalCheck%20--%3E%7CYes%7C%20LedgerEntries%5BWrite%20Paired%20Debit%20%26%20Credit%20in%20ledger.model.js%5D%0A%20%20%20%20LedgerEntries%20--%3E%20UpdateBal%5BUpdate%20Account%20Balances%5D%0A%20%20%20%20UpdateBal%20--%3E%20Commit%5BCommit%20Transaction%5D%0A%20%20%20%20Commit%20--%3E%20Res%5B201%20Created%20%26%20Trigger%20Email%20Receipt%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="say-it-out-loud" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;I built the Double-Entry Ledger transfer engine in <code>transaction.controller.js</code> to ensure financial integrity. Every transfer executes inside a MongoDB atomic session. The engine verifies that the authenticated user owns the source account, checks that the balance is sufficient, and writes a paired debit and credit record into <code>ledger.model.js</code>. Our schema strictly prohibits updates and deletes on ledger entries, guaranteeing an unalterable audit trail.&quot;</p></blockquote><hr><h2 id="f2-token-blacklist-secure-logout" tabindex="-1">F2: Token Blacklist &amp; Secure Logout <a class="header-anchor" href="#f2-token-blacklist-secure-logout" aria-label="Permalink to &quot;F2: Token Blacklist &amp; Secure Logout&quot;">​</a></h2><p>Invalidates JWTs upon user logout by writing the token signature to a TTL-indexed MongoDB collection.</p><h3 id="say-it-out-loud-1" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud-1" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;Because JWTs are stateless by design, logging out usually leaves tokens valid until expiration. In <code>auth.controller.js</code> and <code>blackList.model.js</code>, I implemented an active token blacklist. When a user logs out, their token is saved to MongoDB with a TTL index matching the token expiration time. Our auth middleware checks this blacklist before verifying signatures, instantly revoking compromised or logged-out sessions.&quot;</p></blockquote><hr><h2 id="f3-payee-beneficiary-management" tabindex="-1">F3: Payee Beneficiary Management <a class="header-anchor" href="#f3-payee-beneficiary-management" aria-label="Permalink to &quot;F3: Payee Beneficiary Management&quot;">​</a></h2><p>Allows users to save frequently used bank accounts with strict account number validation.</p><h3 id="say-it-out-loud-2" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud-2" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;To streamline transfers, I built the Beneficiary Management feature in <code>beneficiary.controller.js</code>. Users can save verified account numbers with custom nicknames. The controller enforces 24-character hex ID validation and verifies account ownership to prevent IDOR vulnerabilities when managing payees.&quot;</p></blockquote><hr><h2 id="f4-financial-statement-csv-exporter" tabindex="-1">F4: Financial Statement CSV Exporter <a class="header-anchor" href="#f4-financial-statement-csv-exporter" aria-label="Permalink to &quot;F4: Financial Statement CSV Exporter&quot;">​</a></h2><p>Compiles transaction history into downloadable financial statements formatted for spreadsheet accounting.</p><h3 id="say-it-out-loud-3" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud-3" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;For account holders needing physical records, I built the CSV export endpoint in <code>transaction.controller.js</code>. It queries the user&#39;s completed transactions, formats them with RFC-compliant headers including transaction ID, timestamp, counterparty, and amount, and streams the CSV file directly to the browser.&quot;</p></blockquote><hr><h2 id="f5-real-time-react-banking-dashboard" tabindex="-1">F5: Real-Time React Banking Dashboard <a class="header-anchor" href="#f5-real-time-react-banking-dashboard" aria-label="Permalink to &quot;F5: Real-Time React Banking Dashboard&quot;">​</a></h2><p>Single-page interface displaying current liquidity, recent transfer activity, and quick transfer shortcuts.</p><h3 id="say-it-out-loud-4" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud-4" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;On the client side, I engineered the React banking dashboard in <code>Dashboard.jsx</code>. It utilizes Axios interceptors to automatically attach JWT authorization headers and handle 401 session expirations, updating account balances and recent transfer cards dynamically without page reloads.&quot;</p></blockquote>',22))])}const C=n(h,[["render",m]]);export{q as __pageData,C as default};
